INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Betroffenenrechte > Recht auf Information
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Gewährt das Recht auf Information gemäß DSGVO den Betroffenen Zugang zu Details über die Verarbeitung ihrer personenbezogenen Daten?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 13 und 14 DSGVO verpflichten zur Information"}, {"text": "Nein", "correct": false, "because": "Informationspflicht ist zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Unternehmen laut DSGVO die Betroffenen immer proaktiv über die Datenverarbeitung informieren?', 2, '[{"text": "Ja", "correct": true, "because": "Proaktive Information ist bei Datenerhebung Pflicht"}, {"text": "Nein", "correct": false, "because": "Pflicht besteht bei Erhebung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Recht auf Information ohne eine Datenschutzerklärung erfüllt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Datenschutzerklärung ist übliches Mittel zur Information"}, {"text": "Ja", "correct": false, "because": "Ohne Information fehlt Transparenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Betroffene ihr Recht auf Information auch nach der Datenerhebung ausüben?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 15 DSGVO erlaubt nachträgliche Auskunft"}, {"text": "Nein", "correct": false, "because": "Recht gilt jederzeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Recht auf Information gemäß DSGVO nur für EU-Bürger relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Betroffenen, deren Daten verarbeitet werden"}, {"text": "Ja", "correct": false, "because": "Anwendung ist umfassender"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das Recht auf Information gemäß DSGVO?', 2, '[{"text": "Transparenz über Datenverarbeitung schaffen", "correct": true, "because": "Betroffene sollen Verarbeitung verstehen"}, {"text": "Maximierung der Datenerhebung", "correct": false, "because": "Kein Ziel"}, {"text": "Kostenreduktion", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Artikel der DSGVO regelt die Informationspflicht bei direkter Datenerhebung?', 3, '[{"text": "Art. 13", "correct": true, "because": "Regelt Information bei Erhebung vom Betroffenen"}, {"text": "Art. 14", "correct": false, "because": "Indirekte Erhebung"}, {"text": "Art. 15", "correct": false, "because": "Auskunftsrecht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information muss gemäß DSGVO zwingend bereitgestellt werden?', 2, '[{"text": "Identität des Verantwortlichen", "correct": true, "because": "Pflicht nach Art. 13 und 14"}, {"text": "Softwareversion", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Serverstandort", "correct": false, "because": "Nur bei Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel wird am häufigsten genutzt, um das Recht auf Information zu erfüllen?', 2, '[{"text": "Datenschutzerklärung", "correct": true, "because": "Standardinstrument für Transparenz"}, {"text": "E-Mail-Benachrichtigung", "correct": false, "because": "Situativ"}, {"text": "Telefonanruf", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht, wenn das Recht auf Information nicht erfüllt wird?', 2, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen Art. 13/14 strafbar"}, {"text": "Systemstilllegung", "correct": false, "because": "Keine Standardstrafe"}, {"text": "Geringere Nutzerfreundlichkeit", "correct": false, "because": "Indirekt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Informationen müssen gemäß DSGVO den Betroffenen bereitgestellt werden?', 4, '[{"text": "Identität des Verantwortlichen", "correct": true, "because": "Pflicht nach Art. 13/14"}, {"text": "Zweck der Verarbeitung", "correct": true, "because": "Transparenz über Nutzung"}, {"text": "Rechtsgrundlage", "correct": true, "because": "Legitimation erforderlich"}, {"text": "Softwareentwicklungszeit", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Mittel unterstützen das Recht auf Information?', 3, '[{"text": "Datenschutzerklärung", "correct": true, "because": "Hauptinstrument"}, {"text": "Informationsschreiben", "correct": true, "because": "Bei Erhebung üblich"}, {"text": "Auskunftsantwort", "correct": true, "because": "Art. 15 Antwort"}, {"text": "Unbeschränkte Datenspeicherung", "correct": false, "because": "Kein Informationsmittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten haben Unternehmen im Rahmen des Rechts auf Information?', 4, '[{"text": "Proaktive Information bei Erhebung", "correct": true, "because": "Art. 13 Pflicht"}, {"text": "Angabe der Speicherdauer", "correct": true, "because": "Transparenz über Dauer"}, {"text": "Mitteilung der Betroffenenrechte", "correct": true, "because": "Pflicht nach Art. 13/14"}, {"text": "Maximale Datenerhebung", "correct": false, "because": "Widerspricht DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Verstoß gegen das Recht auf Information haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen Art. 13/14 strafbar"}, {"text": "Schadensersatzansprüche", "correct": true, "because": "Betroffene können klagen"}, {"text": "Vertrauensverlust", "correct": true, "because": "Kundenvertrauen schwindet"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Keine Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte des Rechts auf Information sind bei der Softwareplanung zu beachten?', 3, '[{"text": "Transparente Datenschutzerklärung", "correct": true, "because": "Pflichtinformation"}, {"text": "Angabe der Verarbeitungszwecke", "correct": true, "because": "Transparenz sicherstellen"}, {"text": "Nachweis der Informationspflicht", "correct": true, "because": "Rechenschaftspflicht"}, {"text": "Hohe Datenmenge", "correct": false, "because": "Widerspricht Minimierung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Recht auf Information erfordert eine Datenschutzerklärung. b) Betroffene müssen nicht informiert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenschutzerklärung ja, Information Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unternehmen müssen proaktiv über die Datenverarbeitung informieren. b) Das Recht gilt nur für EU-Bürger.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Proaktiv ja, alle Betroffenen betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Art. 13 regelt die Informationspflicht bei Datenerhebung. b) Verstöße führen nie zu Bußgeldern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Art. 13 ja, Bußgelder möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Betroffene können nachträglich Informationen anfordern. b) Eine Datenschutzerklärung ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nachtrag ja, Erklärung Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Zweck der Verarbeitung muss transparent mitgeteilt werden. b) Das Recht auf Information gilt nur bei direkter Erhebung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zweck ja, auch indirekte Erhebung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

